<?php
require_once __DIR__.'/bootstrap/app.php';require_role('SUPER_ADMIN');$rows=db_all("SELECT mp.MembershipPaymentID,mp.TransactionReference,mp.Amount,mp.Currency,mp.Status,mp.Provider,mp.CardBrand,mp.CardLast4,mp.PaidAt,m.Name MemberName,s.PlanNameSnapshot FROM MEMBERSHIP_PAYMENT mp JOIN MEMBER m ON m.MemberID=mp.MemberID JOIN SUBSCRIPTION s ON s.SubscriptionID=mp.SubscriptionID ORDER BY mp.CreatedAt DESC LIMIT 250");$legacy=db_all("SELECT p.*,m.Name MemberName,t.Name TrainerName FROM PAYMENT p LEFT JOIN MEMBER m ON m.MemberID=p.MemberID LEFT JOIN TRAINER t ON t.TrainerID=p.TrainerID ORDER BY p.PaymentDate DESC,p.PaymentID DESC LIMIT 100");$pageTitle='Payments';$pageSubtitle='Simulated membership transactions and preserved legacy records';include ROOT_PATH.'/includes/header.php';?><div class="demo-banner"><strong>Educational simulation</strong><span>No external payment processor is connected and no full card details are stored.</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th scope="col">Reference</th><th scope="col">Member / plan</th><th scope="col">Amount</th><th scope="col">Method</th><th scope="col">Status</th><th scope="col">Paid</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><code><?=e($r['TransactionReference'])?></code></td><td><?=e($r['MemberName'])?><br><small><?=e($r['PlanNameSnapshot'])?></small></td><td><?=e($r['Currency'])?> <?=number_format((float)$r['Amount'],2)?></td><td><?=e($r['Provider'])?><?=$r['CardLast4']?'<br><small>'.e($r['CardBrand']).' •••• '.e($r['CardLast4']).'</small>':''?></td><td><span class="badge badge-green"><?=e($r['Status'])?></span></td><td><?=e($r['PaidAt']??'—')?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="empty-state">No simulated payments yet.</td></tr><?php endif;?></tbody></table></div><div class="section-header section-spaced"><h2 class="section-title">Legacy payment archive</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th scope="col">ID</th><th scope="col">Party</th><th scope="col">Type</th><th scope="col">Amount</th><th scope="col">Date</th></tr></thead><tbody><?php foreach($legacy as $r):?><tr><td>#<?=$r['PaymentID']?></td><td><?=e($r['MemberName']??$r['TrainerName']??'Unknown')?></td><td><?=e($r['PaymentType'])?></td><td>Rs.<?=number_format((float)$r['Amount'],2)?></td><td><?=e($r['PaymentDate'])?></td></tr><?php endforeach;?></tbody></table></div><?php include ROOT_PATH.'/includes/footer.php';?>
